            mstore(0x00, selector)
            mstore(0x04, and(from, shr(96, not(0))))
            mstore(0x24, and(to, shr(96, not(0))))
            mstore(0x44, value)
            success := call(gas(), token, 0, 0x00, 0x64, 0x00, 0x20)
            // if call success and return is true, all is good.
            // otherwise (not success or return is not true), we need to perform further checks
            if iszero(and(success, eq(mload(0x00), 1))) {
                // if the call was a failure and bubble is enabled, bubble the error
                if and(iszero(success), bubble) {
                    returndatacopy(fmp, 0x00, returndatasize())
                    revert(fmp, returndatasize())
                }
                // if the return value is not true, then the call is only successful if:
                // - the token address has code
                // - the returndata is empty
                success := and(success, and(iszero(returndatasize()), gt(extcodesize(token), 0)))
            }
            mstore(0x40, fmp)
            mstore(0x60, 0)
        }
    }

    /**
     * @dev Imitates a Solidity `token.approve(spender, value)` call, relaxing the requirement on the return value:
     * the return value is optional (but if data is returned, it must not be false).
     *
     * @param token The token targeted by the call.
     * @param spender The spender of the tokens
     * @param value The amount of token to approve
     * @param bubble Behavior switch if the approve call reverts: bubble the revert reason or return a false boolean.
     */
    function _safeApprove(IERC20 token, address spender, uint256 value, bool bubble) private returns (bool success) {
        bytes4 selector = IERC20.approve.selector;

        assembly ("memory-safe") {
            let fmp := mload(0x40)
            mstore(0x00, selector)
            mstore(0x04, and(spender, shr(96, not(0))))
            mstore(0x24, value)
            success := call(gas(), token, 0, 0x00, 0x44, 0x00, 0x20)
            // if call success and return is true, all is good.
            // otherwise (not success or return is not true), we need to perform further checks
            if iszero(and(success, eq(mload(0x00), 1))) {
                // if the call was a failure and bubble is enabled, bubble the error
                if and(iszero(success), bubble) {
                    returndatacopy(fmp, 0x00, returndatasize())
                    revert(fmp, returndatasize())
                }
                // if the return value is not true, then the call is only successful if:
                // - the token address has code
                // - the returndata is empty
                success := and(success, and(iszero(returndatasize()), gt(extcodesize(token), 0)))
            }
            mstore(0x40, fmp)
        }
    }
}

src/rfq/SealedBid.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {BidDeposit} from "./BidDeposit.sol";

/// @title SealedBid
/// @notice Commit-reveal sealed bids. During Bidding a supplier posts only
///         `computeCommitment(rfqId, bidder, price, deliverySeconds, salt)` plus the deposit, so no
///         price is visible on-chain until the reveal window. The salt is generated client-side
///         (never `block.prevrandao`, which is 0 on Arc). A bid that is not revealed in time forfeits
///         its deposit.
abstract contract SealedBid is BidDeposit {
    function computeCommitment(
        uint256 rfqId,
        address bidder,
        uint128 price,
        uint32 deliverySeconds,
        bytes32 proposalHash,
        bytes32 salt
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(address(this), block.chainid, rfqId, bidder, price, deliverySeconds, proposalHash, salt)
        );
    }

    function commitBid(uint256 rfqId, bytes32 commitHash) external nonReentrant {
        _commit(rfqId, commitHash);
    }

    function commitBidWithPermit(
        uint256 rfqId,
        bytes32 commitHash,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external nonReentrant {
        _permit(_rfq(rfqId).depositAmount, deadline, v, r, s);
        _commit(rfqId, commitHash);
    }

    /// @notice Reveal a committed bid. Only the bidder can reveal, only in the reveal window.
    /// @dev `proposalHash` is bound into the commitment, so an RFP proposal cannot be rewritten
    ///      after seeing the competition any more than the price can.
    function revealBid(uint256 rfqId, uint128 price, uint32 deliverySeconds, bytes32 proposalHash, bytes32 salt)
        external
    {
        RFQ storage r = _rfq(rfqId);
        _requirePhase(r, Phase.Reveal);
        Bid storage b = _bids[rfqId][msg.sender];
        if (b.commitHash == bytes32(0)) revert NoCommitment(msg.sender);
        if (b.revealed) revert AlreadyRevealed(msg.sender);
        if (price == 0) revert ZeroPrice();
        if (r.requiresProposal && proposalHash == bytes32(0)) revert ProposalRequired();
        if (computeCommitment(rfqId, msg.sender, price, deliverySeconds, proposalHash, salt) != b.commitHash) {
            revert CommitmentMismatch();
        }

        b.revealed = true;
        b.price = price;
        b.deliverySeconds = deliverySeconds;
        b.proposalHash = proposalHash;
        r.revealCount++;
        _trackCheapest(r, price);
        emit BidRevealed(rfqId, msg.sender, price, deliverySeconds, proposalHash);
    }

    /**
     * @notice Bid on an open tender, in the clear.
     * @dev The whole of the difference between the two modes. There is no commitment and nothing to
     *      reveal later: the price is public the moment it is placed, which is what makes an open
     *      tender open and what costs it the integrity claim a sealed one carries. A bidder may
     *      improve their own bid while bidding is open — that is the point of an open auction — and
     *      the deposit is taken once, exactly as `_commit` does.
     */
    function placeOpenBid(uint256 rfqId, uint128 price, uint32 deliverySeconds, bytes32 proposalHash)
        external
        nonReentrant
    {
        RFQ storage r = _rfq(rfqId);
        if (r.bidMode != BidMode.Open) revert WrongBidMode();
        _requirePhase(r, Phase.Bidding);
        if (price == 0) revert ZeroPrice();
        if (r.requiresProposal && proposalHash == bytes32(0)) revert ProposalRequired();
        _screenBidder(r, rfqId);

        Bid storage b = _bids[rfqId][msg.sender];
        if (b.deposit == DepositState.None) {
            b.deposit = DepositState.Held;
            r.commitCount++;
            r.revealCount++;
            _takeDeposit(r, msg.sender);
        }
        b.price = price;
        b.deliverySeconds = deliverySeconds;
        b.proposalHash = proposalHash;
        b.revealed = true;
        _trackCheapest(r, price);
        emit BidPlaced(rfqId, msg.sender, price, deliverySeconds, proposalHash, r.depositAmount);
    }

    /**
     * @dev The two cheapest revealed prices, updated in place as bids arrive.
     *
     * Bids live in a mapping and this contract refuses to loop over bidders anywhere, so the
     * cheapest alternative to a winner has to be known by the time it is needed rather than
     * searched for afterwards. Used to measure what a default actually costs the buyer.
     *
     * A bidder improving their own open bid can only lower these, never raise them, so the figure
     * stays a floor on what re-procuring would have cost.
     */
    function _trackCheapest(RFQ storage r, uint128 price) internal {
        if (r.lowestRevealed == 0 || price < r.lowestRevealed) {
            r.secondLowestRevealed = r.lowestRevealed;
            r.lowestRevealed = price;
        } else if (r.secondLowestRevealed == 0 || price < r.secondLowestRevealed) {
            r.secondLowestRevealed = price;
        }
    }

    /// @dev Who may bid at all: not the buyer, invited if invite-only, qualified if required.
    function _screenBidder(RFQ storage r, uint256 rfqId) internal view {
        if (msg.sender == r.buyer) revert BuyerCannotBid();
        if (r.inviteOnly && !_invited[rfqId][msg.sender]) revert NotInvited(msg.sender);
        if (
            r.requiresQualification
                && (address(qualifier) == address(0) || !qualifier.isQualified(msg.sender))
        ) {
            revert NotQualified(msg.sender);
        }
    }

    /// @dev Re-committing before the deadline replaces the hash without a second deposit.
    function _commit(uint256 rfqId, bytes32 commitHash) internal {
        RFQ storage r = _rfq(rfqId);
        if (r.bidMode != BidMode.Sealed) revert WrongBidMode();
        _requirePhase(r, Phase.Bidding);
        if (commitHash == bytes32(0)) revert CommitmentMismatch();
        _screenBidder(r, rfqId);

        Bid storage b = _bids[rfqId][msg.sender];
        if (b.deposit == DepositState.None) {
            b.deposit = DepositState.Held;
            r.commitCount++;
            _takeDeposit(r, msg.sender);
        }
        b.commitHash = commitHash;
        emit BidCommitted(rfqId, msg.sender, commitHash, r.depositAmount);
    }
}

src/lib/PullPayments.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @title PullPayments
/// @notice Pull-over-push payouts in a single ERC-20 (Arc USDC).
/// @dev Contracts never force-send. Payouts are credited and beneficiaries call `withdraw()`.
///      If a transfer reverts (e.g. the recipient is on Arc's protocol blocklist), the whole
///      `withdraw()` reverts and the credit stays parked. No milestone or refund is ever bricked
///      by a bad recipient, and funds are never redirected elsewhere.
abstract contract PullPayments is ReentrancyGuard {
    using SafeERC20 for IERC20;

    IERC20 public immutable settlementToken;

    /// @notice Withdrawable balance per beneficiary (6-decimal USDC units).
    mapping(address => uint256) public withdrawable;
    /// @notice Sum of all `withdrawable` balances. Invariant: <= token balance of this contract.
    uint256 public totalWithdrawable;

    event Credited(address indexed beneficiary, uint256 amount);
    event Withdrawn(address indexed beneficiary, uint256 amount);

    error ZeroAddress();
    error ZeroAmount();
    error NothingToWithdraw();

    constructor(IERC20 token) {
        if (address(token) == address(0)) revert ZeroAddress();
        settlementToken = token;
    }

    /// @notice Withdraw everything credited to the caller.
    function withdraw() external nonReentrant returns (uint256 amount) {
        amount = withdrawable[msg.sender];
        if (amount == 0) revert NothingToWithdraw();
        withdrawable[msg.sender] = 0;
        totalWithdrawable -= amount;
        emit Withdrawn(msg.sender, amount);
        settlementToken.safeTransfer(msg.sender, amount);
    }

    /// @dev Pull `amount` from `from` into this contract. Caller must have approved (or used permit).
    function _pullIn(address from, uint256 amount) internal {
        if (amount == 0) revert ZeroAmount();
        settlementToken.safeTransferFrom(from, address(this), amount);
    }

    /// @dev Credit a beneficiary. Funds must already be held by this contract.
    function _credit(address beneficiary, uint256 amount) internal {
        if (beneficiary == address(0)) revert ZeroAddress();
        if (amount == 0) return;
        withdrawable[beneficiary] += amount;
        totalWithdrawable += amount;
        emit Credited(beneficiary, amount);
    }
}

src/interfaces/IAttestationLog.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

/// @title IAttestationLog
/// @notice Append-only log of AI and agent decision hashes: approvals *and* rejections.
///         `payloadHash` is sha256(JCS(memo)) of a `sealedrfq.decision.v1` memo. Anyone can re-hash
///         the published memo and compare it with the anchor (`verify_decision_hash`).
interface IAttestationLog {
    struct Attestation {
        address actor;
        uint64 ts;
        bytes32 kind;
        bytes32 model;
    }

    event Attested(
        uint256 indexed subjectId,
        bytes32 indexed payloadHash,
        bytes32 indexed kind,
        address actor,
        bytes32 model
    );
    event KindRoleSet(bytes32 indexed kind, bytes32 indexed role);

    error UnknownKind(bytes32 kind);
    error NotAuthorizedForKind(address caller, bytes32 kind);
    error AlreadyAttested(uint256 subjectId, bytes32 payloadHash);
    error ZeroHash();

    /// @notice Anchor a decision. Caller must hold the role mapped to `kind`.
    /// @param subjectId rfqId for RFQ decisions; RFQRegistry.awardSubject(rfqId, winner) for
    ///        AWARD_RECOMMENDATION (binds the recommended winner); uint160(supplier) for QUALIFICATION.
    function attest(bytes32 kind, uint256 subjectId, bytes32 payloadHash, bytes32 model) external;

    function getAttestation(uint256 subjectId, bytes32 payloadHash) external view returns (Attestation memory);

    function isAttested(uint256 subjectId, bytes32 payloadHash, bytes32 kind) external view returns (bool);

    function kindRole(bytes32 kind) external view returns (bytes32);

    function setKindRole(bytes32 kind, bytes32 role) external;
}

src/interfaces/IProcurementPolicy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

/// @title IProcurementPolicy
/// @notice On-chain caps that no key (AI agent or human) can cross. RFQRegistry calls
///         `checkCreate` in createRFQ and `checkAward` inside `award()`; a violation reverts the
///         whole transaction with a typed error. "AI proposes, the contract disposes."
interface IProcurementPolicy {
    struct Policy {
        /// Award price cap as a share of the published budget (10000 = the full budget).
        uint16 maxAwardBps;
        /// Revealed bids required before any award.
        uint16 minRevealedBids;
        /// Winner's deposit must be at least this share of its bid price.
        uint16 minDepositBps;
        /// Buyer stake floor at RFQ creation (share of budget).
        uint16 minBuyerStakeBps;
        /// One supplier's share of a buyer's cumulative awarded spend (10000 = no cap).
        uint16 maxSupplierShareBps;
        /// Concentration cap only applies once the buyer's cumulative spend reaches this (6d USDC).
        uint128 concentrationFloor;
        /// Most an AWARDER may commit without the buyer pressing the button themselves (6d USDC).
        ///
        /// The buyer is never capped — this bounds what an agent decides unattended. Zero disables
        /// agent awards entirely, which is the fail-safe reading: a deployment that forgets to set
        /// this gets a human in the loop rather than an uncapped robot. Set it deliberately.
        uint128 agentAwardCap;
    }

    struct AwardCheck {
        uint256 budget;
        uint256 price;
        uint256 deposit;
        uint256 revealedBids;
        bytes32 rubricHash;
        bytes32 expectedRubricHash;
        /// Buyer's cumulative awarded spend before this award.
        uint256 buyerAwardedTotal;
        /// Buyer's cumulative awarded spend with this supplier before this award.
        uint256 buyerSupplierTotal;
    }

    event PolicyUpdated(Policy policy);

    error InvalidPolicy();
    error BuyerStakeTooLow(uint256 bps, uint256 minBps);
    error RubricMismatch(bytes32 got, bytes32 expected);
    error InsufficientBidders(uint256 revealed, uint256 required);
    error AwardExceedsBudget(uint256 price, uint256 cap);
    error DepositRatioTooLow(uint256 deposit, uint256 required);
    error ConcentrationCapExceeded(uint256 shareBps, uint256 maxBps);

    function policy() external view returns (Policy memory);

    function setPolicy(Policy calldata p) external;

    /// @dev Reverts if an RFQ with these terms may not be created.
    function checkCreate(uint256 buyerStakeBps) external view;

    /// @dev Reverts with the first violated rule. Checked in this order: rubric, bidders, budget,
    ///      deposit ratio, concentration.
    function checkAward(AwardCheck calldata c) external view;
}

src/interfaces/ISealedRFQAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

/// @title ISealedRFQAdapter
/// @notice The post-award half of SealedRFQ: turns an award into a milestone engagement on top of
///         ERC-8183. One ACP job per milestone, opened sequentially. The adapter is each job's
///         `client` (it holds the buyer's escrow), its `evaluator` (so acceptance can time out to
///         auto-release on-chain) and its `hook` (enforces the delivery deadline, records submission).
///
///  Per milestone i:  gross_i = price * bps_i (last takes the remainder)
///                    retention_i = gross_i * retentionBps   -> held here until final acceptance
///                    job budget  = gross_i - retention_i     -> escrowed in AgenticCommerce
///  Supplier submits on the ACP job. Buyer (or an attested VERIFIER) accepts or rejects; silence for
///  `acceptanceWindow` lets anyone autoRelease. Final acceptance releases retention + the
///  performance stake to the supplier and the buyer stake back to the buyer.
///  Rejection opens a dispute window: the supplier may escalate to ARBITER, else the buyer is made
///  whole. Missing a delivery deadline abandons the engagement in the buyer's favour.
interface ISealedRFQAdapter {
    enum EngagementStatus {
        None,
        Active,
        Completed,
        Rejected,
        Disputed,
        Resolved,
        Abandoned
    }

    struct EngagementTerms {
        address buyer;
        address supplier;
        uint128 price;
        uint128 buyerStake;
        uint128 performanceStake;
        uint16 retentionBps;
        uint32 deliveryWindow;
        uint32 acceptanceWindow;
        /// @dev Allowance for goods to reach the buyer when they never confirm receipt. Zero for
        ///      anything delivered as a file, which makes the release timing identical to before.
        uint32 transitWindow;
        /// @dev What re-procuring would have cost above this award, measured from the next
        ///      cheapest revealed bid. Zero when no cheaper alternative existed to measure against.
        uint128 excessCost;
        uint16[] milestoneBps;
    }

    struct Engagement {
        address buyer;
        address supplier;
        EngagementStatus status;
        uint8 milestoneCount;
        uint8 currentMilestone;
        uint16 retentionBps;
        uint32 deliveryWindow;
        uint32 acceptanceWindow;
        uint32 transitWindow;
        uint128 price;
        uint128 allocated; // gross amount of milestones opened so far
        uint128 buyerStake;
        uint128 performanceStake;
        uint128 retentionHeld;
        uint128 currentJobBudget;
        /// @dev Retention withheld from the milestone currently open. Tracked apart from
        ///      `retentionHeld` because that total includes it, and retention on a milestone
        ///      nobody delivered is not money the supplier earned.
        uint128 currentRetention;
        uint128 excessCost;
        uint256 currentJobId;
        uint64 deliveryDeadline;
        uint64 submittedAt;
        /// @dev When the buyer acknowledged the goods arrived. Zero until they do; the inspection
        ///      clock runs from here when it is set, and from `submittedAt + transitWindow` when
        ///      it never is, so a silent buyer delays payment but cannot withhold it.
        uint64 receivedAt;
        uint64 disputeDeadline;
        bytes32 deliverable;
    }

    event EngagementStarted(
        uint256 indexed rfqId,
        address indexed buyer,
        address indexed supplier,
        uint256 price,
        uint8 milestones
    );
    event MilestoneFunded(
        uint256 indexed rfqId,
        uint8 indexed index,
        uint256 indexed jobId,
        uint256 jobBudget,
        uint256 retention,
        uint64 deliveryDeadline
    );
    event MilestoneSubmitted(
        uint256 indexed rfqId, uint8 indexed index, uint256 indexed jobId, bytes32 deliverable
    );
    event MilestoneAccepted(
        uint256 indexed rfqId,
        uint8 indexed index,
        uint256 indexed jobId,
        bytes32 reason,
        address by,
        bool automatic
    );
    event MilestoneRejected(
        uint256 indexed rfqId, uint8 indexed index, uint256 indexed jobId, bytes32 reason, address by
    );
    event DisputeRaised(uint256 indexed rfqId, address indexed by);
    event DisputeResolved(uint256 indexed rfqId, uint256 toSupplier, uint256 toBuyer, bytes32 reason);
    event RejectionFinalized(uint256 indexed rfqId, uint256 toBuyer);
    /// @notice The buyer says the goods arrived. Starts the inspection clock; decides nothing.
    event ReceiptConfirmed(uint256 indexed rfqId, uint8 indexed milestone, uint64 at);
    /// @notice The buyer gave the supplier more time, before the original window ran out.
    event DeliveryExtended(uint256 indexed rfqId, uint8 indexed milestone, uint64 newDeadline);
    event EngagementCompleted(uint256 indexed rfqId, uint256 toSupplier, uint256 toBuyer);
    /// @notice Nothing was delivered in time. `toBuyer` covers their loss; `toSupplier` is what
    ///         was at risk and not needed to cover it.
    event EngagementAbandoned(uint256 indexed rfqId, uint256 toBuyer, uint256 toSupplier);

    error NotFound(uint256 rfqId);
    error AlreadyStarted(uint256 rfqId);
    error InvalidTerms();
    error WrongStatus(EngagementStatus status);
    error WrongJobStatus();
    error NotBuyerOrVerifier(address caller);
    error NotSupplier(address caller);
    error ReasonNotAttested(bytes32 reason);
    error ReasonRequired();
    error AcceptanceWindowOpen(uint64 releasesAt);
    error DeliveryWindowClosed(uint64 deadline);
    error DisputeWindowClosed(uint64 deadline);
    error DisputeWindowOpen(uint64 deadline);
    error NotExpired();
    /// @dev Settlement was asked for while the supplier still had time to deliver.
    error DeliveryWindowOpen(uint64 deadline);
    error NotBuyer(address caller);
    error AlreadyReceived();
    error NothingSubmitted();
    /// @dev An extension must move the deadline forward, and not past the job's own expiry.
    error BadExtension(uint64 latest);
    error OnlyAgenticCommerce();
    error InvalidBps();

    /// @notice Only the RFQRegistry (REGISTRY role). Pulls price + stakes from the caller.
    function startEngagement(uint256 rfqId, EngagementTerms calldata t) external;

    function acceptMilestone(uint256 rfqId, bytes32 reason) external;
    function rejectMilestone(uint256 rfqId, bytes32 reason) external;
    /// @notice Anyone, once `acceptanceWindow` has passed since submission.
    function autoRelease(uint256 rfqId) external;
    /// @notice Anyone, once the current job has expired (delivered-but-unreviewed pays the supplier;
    ///         never-delivered abandons in the buyer's favour).
    function settleExpired(uint256 rfqId) external;

    function raiseDispute(uint256 rfqId) external;
    function finalizeRejection(uint256 rfqId) external;
    function resolveDispute(uint256 rfqId, uint16 supplierBps, bytes32 reason) external;

    function getEngagement(uint256 rfqId) external view returns (Engagement memory);
    function milestoneBps(uint256 rfqId) external view returns (uint16[] memory);
    function jobToRfq(uint256 jobId) external view returns (uint256);
}

src/governance/Roles.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

/// @title Roles
/// @notice Least-privilege role ids shared by every SealedRFQ contract (OZ AccessControl).
/// @dev Each contract keeps its own role membership; `script/Configure.s.sol` grants per contract.
///      EVALUATOR scores and attests but cannot award. AWARDER awards within policy only. VERIFIER
///      accepts/rejects milestones but cannot award or refund deposits. ARBITER only splits disputed
///      escrow. REGISTRY is the RFQRegistry contract itself, the only caller that opens engagements.
library Roles {
    bytes32 internal constant ADMIN = 0x00; // OZ DEFAULT_ADMIN_ROLE
    bytes32 internal constant EVALUATOR = keccak256("sealedrfq.role.EVALUATOR");
    bytes32 internal constant AWARDER = keccak256("sealedrfq.role.AWARDER");
    bytes32 internal constant VERIFIER = keccak256("sealedrfq.role.VERIFIER");
    bytes32 internal constant ATTESTOR = keccak256("sealedrfq.role.ATTESTOR");
    bytes32 internal constant ARBITER = keccak256("sealedrfq.role.ARBITER");
    bytes32 internal constant REGISTRY = keccak256("sealedrfq.role.REGISTRY");
}

/// @title AttestationKinds
/// @notice Decision kinds anchored in AttestationLog. Mirrors `DecisionKind` in
///         `packages/shared/src/memo.ts` (sealedrfq.decision.v1).
library AttestationKinds {
    bytes32 internal constant BID_EVALUATION = "BID_EVALUATION";
    bytes32 internal constant AWARD_RECOMMENDATION = "AWARD_RECOMMENDATION";
    bytes32 internal constant AWARD_REJECTION = "AWARD_REJECTION";
    bytes32 internal constant MILESTONE_ACCEPT = "MILESTONE_ACCEPT";
    bytes32 internal constant MILESTONE_REJECT = "MILESTONE_REJECT";
    bytes32 internal constant QUALIFICATION = "QUALIFICATION";
}

